=<active_frame>
{{ JSON.stringify((() => {
      const cur = $('frame-current').first().json;
      const { id, ...frameRest } = cur.frame || {};
      const sem = $('Call \'sub-query-reformulator\'').first().json.output || {};
      const newAL = $('resolve-access-levels').first().json.access_levels_used || [];
      const oldAL = Array.isArray(frameRest.access_levels_used) ? frameRest.access_levels_used : [];

      const norm = a => [...new Set(a.map(x => String(x).toLowerCase()))].sort();
      const changed = JSON.stringify(norm(oldAL)) !== JSON.stringify(norm(newAL));

      const frame = { ...frameRest, access_levels_used: newAL };

      // Override domain/intent from current semantic parse if present
      if (sem.domain_hint && sem.domain_hint !== 'other') frame.domain = sem.domain_hint;
      if (sem.intent_hint) frame.intent = sem.intent_hint;

      // Always drop tools_used to prevent contamination across turns
      frame.tools_used = [];
      if (frame.last_execution) {
        frame.last_execution = { ...frame.last_execution, tools_used: [] };
      }

      if (changed) {
        frame.result_refs = [];
        if (frame.last_execution) {
          frame.last_execution = { ...frame.last_execution, result_refs: [] };
        }   
      }
      return { ...cur, frame };
    })()) }}
</active_frame>

<semantic_parse>
{{ JSON.stringify($('Call \'sub-query-reformulator\'').first().json.output || {}) }}
</semantic_parse>

<resolved_entities>
{{ JSON.stringify(($('get-resolve-entity').first().json.resolutions || []).filter(r => r.matches?.length).map(r => ({ token: r.token, entity_type:
  r.matches[0].entity_type }))) }}
</resolved_entities>

<rag_shortlist ranked by similarity, rank 1 = best>
{{ JSON.stringify(($json.tools || []).map((t, i) => ({ rank: i+1, name: t.name, description: t.description || null, score: t.score ?? t.similarity ?? null }))) }}
</rag_shortlist>

<access_levels>
{{ $('resolve-access-levels').first().json.access_levels_used }}
</access_levels>
<recalled_frame>
{{ $('frame-search').isExecuted ? JSON.stringify((($('frame-search').first().json || {}).frames || [])[0] || null) : [] }}
</recalled_frame>

