// =============================================================================
// n8n Code node: compile-current-state (SIMPLIFIED)
// Mode: Run Once for All Items
//
// All state decisions live HERE, not in the reformulator prompt:
//   - slot-fill detection (when prev frame has pending_request.waiting_for_user)
//   - topic-switch detection (semantic.domain_hint != prev.domain)
//   - memory-recall preference (recalled frame vs current open frame)
//   - escalation confirmation handling
//   - access_levels stickiness
//
// Inputs (referenced by node name):
//   - "Call 'sub-query-reformulator'" .first().json.output
//   - "frame-current"                   .first().json.frame      (or null)
//   - "frame-search"                    .first().json.frames     (may be missing if skipped)
//   - "get-resolve-entity"              .first().json
//   - "tf-message"                      .first().json
//   - "sorento-sub-respond-findcontact-respond" .first().json
//   - $input.first().json                                        (AI Agent output)
//
// Output: one item with { frameAction, turnType, contactId, spaceId, channel,
//                         activeFrame, agentOutput,
//                         frameOpenPayload, frameUpdatePayload, frameClosePayload }
// =============================================================================

const semantic  = $('Call \'sub-query-reformulator\'').first().json.output || {};
const prev      = (($('frame-current').first().json || {}).frame) || {};

let recalled = null;
try {
  const fs = $('frame-search').first().json;
  const arr = (fs && Array.isArray(fs.frames)) ? fs.frames : [];
  if (arr.length > 0) recalled = arr[0];
} catch (e) { /* frame-search node was skipped this turn — fine */ }

const resolver  = $('get-resolve-entity').first().json || {};
const agentOut  = $input.first().json || {};
const contact   = $('sorento-sub-respond-findcontact-respond').first().json || {};
const tfMessage = $('tf-message').first().json || {};

const contactId = contact.id.toString();
const spaceId   = '364817';
const channel   = 'whatsapp';
const latestUserMessage = (
  tfMessage?.message?.message?.text ||
  tfMessage?.message?.message?.attachment?.description ||
  tfMessage?.message || ''
).toString().trim();
const resolvedAccesssLevel = $('resolve-access-levels').first().json.access_levels_used
// ---------- helpers ----------------------------------------------------------
function mergeEntities(baseEntities, resolutions, semanticEntities) {
  const out = Object.assign({}, baseEntities || {});
  for (const r of (resolutions || [])) {
    const best = (r.matches || [])[0];
    if (!best) continue;
    const type = best.entity_type || 'unknown';
    out[type] = {
      raw: r.token,
      canonical_id: best.entity_id || best.id || null,
      canonical_name: best.entity_name || best.name || r.token,
      source: 'entity_resolver',
    };
  }
  if (Object.keys(out).length === 0) {
    for (const e of (semanticEntities || [])) {
      const type = e.type_hint || 'unknown';
      out[type] = { raw: e.raw, type, source: 'semantic_parser' };
    }
  }
  return out;
}

function dedupe(arr) { return Array.from(new Set((arr || []).filter(Boolean))); }

// ---------- detect turn type ------------------------------------------------
const hasPrev        = !!prev.id;
const isWaiting      = (prev.pending_request || {}).status === 'waiting_for_user';
const isReferringBack= !!semantic.reference_to_previous_context;
const isEscConfirm   = !!(semantic.escalation && semantic.escalation.is_escalation_confirmation);
const topicChanged   = hasPrev
                     && semantic.domain_hint
                     && semantic.domain_hint !== 'other'
                     && semantic.domain_hint !== prev.domain;

const RECALL_THRESHOLD = 0.5;
const recallScore = (recalled && typeof recalled.similarity_score === 'number') ? recalled.similarity_score : 0;
const useRecalled =
  recalled !== null &&
  recallScore >= RECALL_THRESHOLD &&
  (!hasPrev || (recalled.domain && recalled.domain !== prev.domain));

let turnType;
if (isEscConfirm)                                          turnType = 'escalation_confirm';
else if (hasPrev && topicChanged)                          turnType = 'topic_switch';
else if (isWaiting)                                        turnType = 'slot_fill';
else if (useRecalled && !hasPrev)                          turnType = 'rehydrate';
else if (useRecalled && hasPrev)                           turnType = 'switch_to_recall';
else if (!hasPrev)                                         turnType = 'new_topic';
else                                                       turnType = 'continue';

const frameAction =
  turnType === 'topic_switch'      ? 'close_and_open' :
  turnType === 'switch_to_recall'  ? 'close_and_open' :
  turnType === 'rehydrate'         ? 'open'           :
  turnType === 'new_topic'         ? 'open'           :
  /* slot_fill | continue | escalation_confirm */          'update';

// ---------- pick seed frame (what active_frame inherits from) ---------------
const seed = (turnType === 'switch_to_recall' || turnType === 'rehydrate')
  ? (recalled || {})
  : (frameAction === 'update' ? prev : {});

// ---------- access_levels resolution ----------------------------------------
const prevAccessLevels    = Array.isArray(prev.access_levels_used)    ? prev.access_levels_used    : [];
const seedAccessLevels    = Array.isArray(seed.access_levels_used)    ? seed.access_levels_used    : [];
const agentAccessLevels   = Array.isArray(agentOut.access_levels_used)? agentOut.access_levels_used: [];



// ---------- pending_request lifecycle ---------------------------------------
const agentPending = (agentOut.state_update || {}).pending_request || null;
let pendingNow;
if (agentPending && Object.keys(agentPending).length > 0) {
  pendingNow = agentPending;                                // agent set new pending this turn
} else if (turnType === 'slot_fill' || turnType === 'escalation_confirm') {
  pendingNow = {};                                          // satisfied — clear
} else {
  pendingNow = prev.pending_request || {};                  // carry forward
}

// ---------- inherit topic on slot_fill / continue / escalation_confirm ------
const inheritTopic = (turnType === 'slot_fill'
                   || turnType === 'continue'
                   || turnType === 'escalation_confirm');
const isFreshFrame = (turnType === 'topic_switch' || turnType === 'new_topic');
let accessLevels;
  if (isFreshFrame) {
    accessLevels = [];                                          // topic_switch / new_topic → drop
  } else if (turnType === 'slot_fill'
      && (prev.pending_request || {}).reason === 'missing_access_level') {
    accessLevels = resolvedAccesssLevel ? resolvedAccesssLevel : prevAccessLevels;
  } else if (turnType === 'switch_to_recall' || turnType === 'rehydrate') {
    accessLevels = seedAccessLevels;
  } else if (agentAccessLevels.length > 0) {
    accessLevels = agentAccessLevels;
  } else {
    accessLevels = resolvedAccesssLevel ? resolvedAccesssLevel : prevAccessLevels;
  }
const activeFrame = {
  domain:  inheritTopic ? (prev.domain || semantic.domain_hint || seed.domain || null)
                        : (semantic.domain_hint || seed.domain || prev.domain || null),
  intent:  inheritTopic ? (prev.intent || semantic.intent_hint || seed.intent || null)
                        : (semantic.intent_hint || seed.intent || prev.intent || null),
    active_entities: mergeEntities({}, resolver.resolutions, semantic.entities),
  //access_levels_used: accessLevels,
  tools_used: dedupe([
    ...(isFreshFrame ? [] : ((seed.tools_used) || (prev.tools_used) || [])),
    ...(((agentOut.state_update || {}).last_execution || {}).tools_used || []),
  ]),
  pending_request: pendingNow,
  last_user_message: latestUserMessage,
  last_assistant_summary:
    ((agentOut.state_update || {}).last_assistant_response || {}).summary
    || agentOut.response_intro
    || null,
};


// ---------- HTTP payloads per branch ---------------------------------------
const frameOpenPayload = {
    contact_id: contactId,
    space_id: spaceId,
    channel,
    domain: activeFrame.domain,
    intent: activeFrame.intent, 
    active_entities: activeFrame.active_entities,
    //access_levels_used: activeFrame.access_levels_used,
    tools_used: activeFrame.tools_used,
    // pending_request: activeFrame.pending_request,
    last_user_message: activeFrame.last_user_message,
    last_assistant_summary: activeFrame.last_assistant_summary,
  };

const frameUpdatePayload = hasPrev ? {
  frame_id: prev.id,
  patch: {
    domain: activeFrame.domain,
    intent: activeFrame.intent,
    active_entities: activeFrame.active_entities,
    //access_levels_used: activeFrame.access_levels_used,
    tools_used: activeFrame.tools_used,
    pending_request: activeFrame.pending_request,
    last_user_message: activeFrame.last_user_message,
    last_assistant_summary: activeFrame.last_assistant_summary,
  },
} : null;

const frameClosePayload = (hasPrev && frameAction === 'close_and_open') ? {
  frame_id: prev.id,
  reason: (turnType === 'switch_to_recall') ? 'topic_switch' : 'topic_switch',
  summary: prev.last_assistant_summary
        || prev.summary
        || prev.last_user_message
        || `Closed (turn=${turnType}).`,
} : null;

return [{
  json: {
    frameAction,                          // "open" | "update" | "close_and_open"
    turnType,                             // useful for debugging in n8n executions
    contactId, spaceId, channel,
    activeFrame,
    agentOutput: agentOut,
    frameOpenPayload,
    frameUpdatePayload,
    frameClosePayload,
  },
}];

// =============================================================================
// n8n Code node: resolve-access-levels
// Mode: Run Once for All Items
// Place AFTER: frame-current, get-contact-access-level, Call sub-query-reformulator
// Place BEFORE: AI Agent
//
// Backend `/external/contact-access-types/active` returns
//   [{ name, keywords: [..] }]
// Multi-match: a single user message can reference multiple access levels
// (e.g. "dealer pricing vs end user pricing"). Loop all catalog entries,
// match by keyword phrase (all phrase-tokens must appear in corpus tokens),
// collect every hit.
//
// Output: { access_levels_used: [<name>...] | [], source, matched[], catalog_size }
// =============================================================================

const prevFrame = (($('frame-current').first().json || {}).frame) || {};
const semantic  = $('Call \'sub-query-reformulator\'').first().json.output || {};
const tfMessage = $('tf-message').first().json || {};

const latestUserMessage = (
  tfMessage?.message?.message?.text ||
  tfMessage?.message?.message?.attachment?.description ||
  tfMessage?.message || ''
).toString();

// ---------- SSOT catalog (handle 3 HTTP-node output shapes) -----------------
const accessCatalog = (() => {
  try {
    const items = $('get-contact-access-level').all() || [];
    const out = [];
    for (const it of items) {
      const j = it && it.json;
      if (!j) continue;
      if (Array.isArray(j)) {
        for (const r of j) if (r && r.name) out.push(r);
        continue;
      }
      if (Array.isArray(j.body)) {
        for (const r of j.body) if (r && r.name) out.push(r);
        continue;
      }
      if (j.name) out.push(j);
    }
    return out;
  } catch (e) { return []; }
})();

const catalogNamesLower = accessCatalog.map(it => String(it.name).toLowerCase());

// ---------- build search corpus from this turn ------------------------------
const corpus = [
  latestUserMessage,
  ...((semantic.entities || []).map(e => (e && e.raw) || '')),
  semantic.user_goal || '',
].join(' ').toLowerCase();

function tokenize(s) {
  return String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length > 0);
}

const corpusTokenSet = new Set(tokenize(corpus));

// ---------- multi-match against catalog -------------------------------------
// For each catalog entry: build phrase list = keywords ?? [name].
// A phrase matches if ALL its tokens appear in corpusTokenSet.
// Score = number of matched phrase-tokens (longer phrases beat single tokens).
// Catalog entry counts as hit if any phrase matches.
const matched = [];
const scoreDebug = [];

for (const it of accessCatalog) {
  const phrases = Array.isArray(it.keywords) && it.keywords.length
    ? it.keywords
    : [it.name];

  let bestPhrase = null;
  let bestScore = 0;
  for (const p of phrases) {
    const pTokens = tokenize(p);
    if (pTokens.length === 0) continue;
    const allPresent = pTokens.every(t => corpusTokenSet.has(t));
    if (allPresent && pTokens.length > bestScore) {
      bestScore = pTokens.length;
      bestPhrase = p;
    }
  }

  scoreDebug.push({ name: it.name, phrases, bestPhrase, bestScore });

  if (bestPhrase) matched.push({ name: it.name, score: bestScore, phrase: bestPhrase });
}

// dedupe by name, keep order of first appearance in catalog
const seen = new Set();
const matchedNames = [];
for (const m of matched) {
  const key = m.name.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  matchedNames.push(m.name);
}

// ---------- validate sticky against catalog ---------------------------------
const prevList = Array.isArray(prevFrame.access_levels_used) ? prevFrame.access_levels_used : [];
const validStickies = prevList.filter(v => v && catalogNamesLower.includes(String(v).toLowerCase()));

// ---------- detect topic-switch (mirrors compile-current-state) ------------
const semDomain = (semantic.domain_hint || '').toLowerCase();
const prevDomain = (prevFrame.domain || '').toLowerCase();
const isFreshFrame =
  !!prevDomain &&
  !!semDomain &&
  semDomain !== 'other' &&
  semDomain !== prevDomain;

// ---------- resolve final access_levels_used --------------------------------
let access_levels_used;
let source;
if (matchedNames.length > 0) {
  access_levels_used = matchedNames;
  source = 'mention';
} else if (isFreshFrame) {
  access_levels_used = [];
  source = 'topic_switch_cleared';
} else if (validStickies.length > 0) {
  access_levels_used = validStickies;
  source = 'sticky';
} else {
  access_levels_used = [];
  source = 'empty';
}

return [{
  json: {
    access_levels_used,
    source,
    matched,              // debug: [{name, score, phrase}]
    catalog_size: accessCatalog.length,
    scoreDebug,           // debug: per-catalog phrase scoring
    droppedStickies: prevList.filter(v => !validStickies.includes(v)),
  },
}];
